    out = [row[:] for row in grid]
    # For each column, continue the vertical pattern of 4 markers: gaps between
    # same-column markers are filled 2 only when the outer boundary pattern
    # identifies that column as a connector. Similarly for rows.
    # Connector coordinates are those repeated as aligned marker tracks.
    rows = [[c for c,v in enumerate(row) if v == 4] for row in grid]
    cols = [[r for r in range(h) if grid[r][c] == 4] for c in range(w)]
    # Draw between aligned endpoints when at least two 4s share an axis.
