        if len(ys) >= 2:
            for r in range(min(ys), max(ys)+1):
                if grid[r][c] == 9: out[r][c] = 2
    for r, xs in enumerate(rows):
        if len(xs) >= 2:
            for c in range(min(xs), max(xs)+1):
                if grid[r][c] == 9: out[r][c] = 2
    return out
